describe('Rate-Limit Error Handling', () => {
  beforeEach(() => {
    cy.visit('/form-submit');
  });

  it('should display rate-limit error when submitting form too many times', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Submit the form 5 times to trigger rate limit
    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    // Verify rate-limit error message is displayed
    cy.get('[data-testid="rate-limit-error-message"]')
      .should('be.visible')
      .should('contain', 'Too many requests');

    // Verify error code is displayed
    cy.get('[data-testid="error-code"]')
      .should('be.visible')
      .should('contain', '429');

    // Verify retry button is available
    cy.get('[data-testid="retry-button"]')
      .should('be.visible')
      .click();

    // Verify form is still visible
    cy.get('[data-testid="form-container"]')
      .should('be.visible');
  });

  it('should not display rate-limit error when submitting within limits', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/form-submit').as('formSubmit');

    // Submit the form 3 times (within rate limit)
    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    cy.get('[data-testid="submit-button"]').click();
    cy.wait('@formSubmit');

    // Verify rate-limit error message is not displayed
    cy.get('[data-testid="rate-limit-error-message"]')
      .should('not.exist');

    // Verify form submission was successful
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .should('contain', 'Form submitted successfully');
  });
});
